shell_commands:
python3 - <<'EOF'
p='src/transport/ws/validation.ts'
s=open(p).read()
old=s[s.index("  switch (message.type) {"):s.index("function validateUserMessage")]
new="""  const validate = Object.hasOwn(VALIDATORS, message.type) ? VALIDATORS[message.type] : undefined;
