  user_message: message => validateUserMessage(message),
  ping: message => validatePingMessage(message),
  list_sessions: message => validateListSessionsMessage(message),
};

export function validateMessage""")
open(p,'w').write(s)
p='src/transport/ws/validation.test.ts'
